14	} from 'react-native';
15	import { useLocalSearchParams, router } from 'expo-router';
16	import { SafeAreaView } from 'react-native-safe-area-context';
17	import { Sprite, statusColor, statusDisplayName } from '@/models/sprite';
18	import { AgentProvider, ChatMessage, providerDisplayName, toolUseActivityLabel } from '@/models/chat';
19	import * as api from '@/services/api';
20	import { useChat } from '@/hooks/useChat';
21	import { useChatDictation } from '@/hooks/useChatDictation';
22	import { useTheme } from '@/hooks/use-theme';
23	import { ChatMessageView } from '@/components/chat/ChatMessageView';
24	import { ChatInputBar } from '@/components/chat/ChatInputBar';
25	import { ChatList } from '@/components/chat/ChatList';
26	import { ChatListSheet } from '@/components/chat/ChatListSheet';
27	import { NewSessionSheet, NewSessionConfig } from '@/components/chat/NewSessionSheet';
28	import { QuickBashSheet } from '@/components/chat/QuickBashSheet';
29	import { AgentSessionSummary, SessionBrowserSheet } from '@/components/chat/SessionBrowserSheet';
30	import { CheckpointsList } from '@/components/checkpoints/CheckpointsList';
31	import { SpriteAccountsTab } from '@/components/sprite/SpriteAccountsTab';
32	import { ActiveChatRun, PersistedChat, chatRepository } from '@/services/chat-repository';
33	import { getSetting, setSetting } from '@/services/storage';
34	import { TranscriptionProvider } from '@/services/client-transcription';
35	import { FontSize, Spacing } from '@/constants/theme';
36	import { DEFAULT_WORKING_DIRECTORY, normalizeWorkingDirectory, shortWorkingDirectory } from '@/constants/session';
37	
38	// The sprite screen is a hub with three tabs. "chats" (center) is the default
39	// and shows the conversation list; opening a conversation switches to a
40	// full-screen chat view (tracked by `chatOpen`) that hides the tab bar.
41	type Tab = 'options' | 'chats' | 'settings';
42	
43	function normalizeProvider(provider: unknown): AgentProvider {
44	  return provider === 'codex' ? 'codex' : 'claude';
45	}
46	
47	function normalizeTranscriptionProvider(provider: unknown): TranscriptionProvider {
48	  return provider === 'assemblyai' || provider === 'openai' ? provider : 'sprite';
49	}
50	
51	/** Find the active tool label from the last assistant message's content */
52	function getActiveToolLabel(
53	  messages: ChatMessage[],
54	  workingDirectory: string
55	): string | undefined {
56	  for (let i = messages.length - 1; i >= 0; i--) {
57	    const msg = messages[i];
58	    if (msg.role !== 'assistant') continue;
59	    for (let j = msg.content.length - 1; j >= 0; j--) {
60	      const item = msg.content[j];
61	      if (item.type === 'toolUse' && !item.card.result) {
62	        return toolUseActivityLabel(item.card, workingDirectory);
63	      }
64	    }
65	    break;
66	  }
67	  return undefined;
68	}
