70	export default function SpriteDetailScreen() {
71	  const { name } = useLocalSearchParams<{ name: string }>();
72	  const colors = useTheme();
73	  const [tab, setTab] = useState<Tab>('chats');
74	  // Whether a single conversation is open full-screen (vs. the 3-tab hub).
75	  const [chatOpen, setChatOpen] = useState(false);
76	  const [sprite, setSprite] = useState<Sprite | null>(null);
77	  const [isLoadingSprite, setIsLoadingSprite] = useState(true);
78	  const flatListRef = useRef<FlatList>(null);
79	
80	  // Multi-chat state
81	  const [chatId, setChatId] = useState<string>('');
82	  const [chatName, setChatName] = useState<string>('Session 1');
83	  const [chatProvider, setChatProvider] = useState<AgentProvider>('claude');
84	  const [claudeSessionId, setClaudeSessionId] = useState<string | undefined>();
85	  const [codexSessionId, setCodexSessionId] = useState<string | undefined>();
86	  const [activeRun, setActiveRun] = useState<ActiveChatRun | undefined>();
87	  const [chatListVisible, setChatListVisible] = useState(false);
88	  const [quickBashVisible, setQuickBashVisible] = useState(false);
89	  const [sessionBrowserVisible, setSessionBrowserVisible] = useState(false);
90	  // Bumped to force the current chat to reload its persisted messages (e.g. after
91	  // seeding a resumed session's transcript) even when chatId is unchanged.
92	  const [reloadNonce, setReloadNonce] = useState(0);
93	  // null = closed. 'new' creates a fresh session; 'edit' changes the current session's directory.
94	  const [sessionSheetMode, setSessionSheetMode] = useState<'new' | 'edit' | null>(null);
95	  // Reactive mirror of chatListRef so the inline Chats tab re-renders on change.
96	  const [chatList, setChatList] = useState<PersistedChat[]>([]);
97	  const chatListRef = useRef<PersistedChat[]>([]);
98	  const appStateRef = useRef(AppState.currentState);
99	
100	  // Update both the synchronous ref (read inside callbacks to avoid stale
101	  // closures) and the reactive state (drives the inline Chats list) together.
102	  const commitChatList = useCallback((next: PersistedChat[]) => {
103	    chatListRef.current = next;
104	    setChatList(next);
105	  }, []);
106	
107	  const spriteName = name ?? '';
108	  const [workingDirectory, setWorkingDirectory] = useState(DEFAULT_WORKING_DIRECTORY);
109	  const [defaultDirectory, setDefaultDirectory] = useState(DEFAULT_WORKING_DIRECTORY);
110	  const [transcriptionProvider, setTranscriptionProvider] =
111	    useState<TranscriptionProvider>('sprite');
112	
113	  const chat = useChat({
114	    spriteName,
115	    chatId,
116	    workingDirectory,
117	    provider: chatProvider,
118	    initialClaudeSessionId: claudeSessionId,
119	    initialCodexSessionId: codexSessionId,
120	    initialActiveRun: activeRun,
121	    onSessionIdsChange: (sessionIds) => {
122	      setClaudeSessionId(sessionIds.claudeSessionId);
123	      setCodexSessionId(sessionIds.codexSessionId);
124	      if (!chatId) return;
125	      const updated = chatListRef.current.map((chatMeta) =>
126	        chatMeta.id === chatId
127	          ? {
128	              ...chatMeta,
129	              claudeSessionId: sessionIds.claudeSessionId,
130	              codexSessionId: sessionIds.codexSessionId,
131	            }
132	          : chatMeta
133	      );
134	      commitChatList(updated);
135	      chatRepository.updateSessionIds(chatId, {
136	        claudeSessionId: sessionIds.claudeSessionId,
137	        codexSessionId: sessionIds.codexSessionId,
138	      });
139	    },
140	    onActiveRunChange: (nextActiveRun) => {
141	      setActiveRun(nextActiveRun);
142	      if (!chatId) return;
143	      const updated = chatListRef.current.map((chatMeta) =>
144	        chatMeta.id === chatId ? { ...chatMeta, activeRun: nextActiveRun } : chatMeta
145	      );
146	      commitChatList(updated);
147	      chatRepository.setActiveRun(chatId, nextActiveRun ?? undefined);
148	    },
149	  });
150	  const dictation = useChatDictation({
151	    spriteName,
152	    workingDirectory,
153	    inputText: chat.inputText,
154	    setInputText: chat.setInputText,
155	    transcriptionProvider,
156	  });
157	  const isProviderLocked = chat.messages.some((message) => message.role === 'user');
158	
159	  // Initialize chat list and current chat on mount
160	  useEffect(() => {
161	    let mounted = true;
162	    (async () => {
163	      const [chats, savedDefaultDir, savedTranscriptionProvider] = await Promise.all([
164	        chatRepository.listBySprite(spriteName),
165	        getSetting('defaultWorkingDirectory'),
166	        getSetting('transcriptionProvider'),
167	      ]);
168	      if (!mounted) return;
169	
170	      const fallbackDir = savedDefaultDir
171	        ? normalizeWorkingDirectory(savedDefaultDir)
172	        : DEFAULT_WORKING_DIRECTORY;
173	      setDefaultDirectory(fallbackDir);
174	      setTranscriptionProvider(normalizeTranscriptionProvider(savedTranscriptionProvider));
175	
176	      if (chats.length > 0) {
177	        commitChatList(chats);
178	        // Point at the most recently used session so the hook can reattach to a
179	        // still-running exec in the background — but stay on the list (chatOpen
180	        // is false) so opening a sprite lands on the conversation list.
181	        const sorted = [...chats].sort((a, b) => b.lastUsed - a.lastUsed);
182	        const current = sorted[0];
183	        setChatId(current.id);
184	        setChatName(current.customName ?? `Session ${current.chatNumber}`);
185	        setChatProvider(normalizeProvider(current.provider));
186	        setClaudeSessionId(current.claudeSessionId);
187	        setCodexSessionId(current.codexSessionId);
188	        setActiveRun(current.activeRun);
189	        setWorkingDirectory(current.workingDirectory || fallbackDir);
190	      } else {
191	        const defaultProvider = normalizeProvider(await getSetting('defaultProvider'));
192	        // Create the first chat
193	        const firstChat: PersistedChat = {
194	          id: `${spriteName}-chat-1`,
195	          spriteName,
196	          chatNumber: 1,
197	          provider: defaultProvider,
198	          workingDirectory: fallbackDir,
199	          createdAt: Date.now(),
200	          lastUsed: Date.now(),
201	          isClosed: false,
202	          lastSessionComplete: true,
203	          processedEventUUIDs: [],
204	        };
205	        commitChatList([firstChat]);
206	        await chatRepository.upsert(firstChat);
207	        setChatId(firstChat.id);
208	        setChatName('Session 1');
209	        setChatProvider(defaultProvider);
210	        setClaudeSessionId(undefined);
211	        setCodexSessionId(undefined);
212	        setActiveRun(undefined);
213	        setWorkingDirectory(fallbackDir);
214	      }
215	    })();
216	    return () => { mounted = false; };
217	  }, [spriteName, commitChatList]);
218	
219	  // Load sprite info
220	  useEffect(() => {
221	    let mounted = true;
222	    (async () => {
223	      try {
224	        const s = await api.getSprite(spriteName);
225	        if (mounted) setSprite(s);
226	      } catch {}
227	      if (mounted) setIsLoadingSprite(false);
228	    })();
229	    return () => { mounted = false; };
230	  }, [spriteName]);
231	
232	  // Old builds ran chat turns as persistent `wisp-*` services. Clean those up
233	  // when the sprite opens so they cannot restart and replay prompts into Claude.
234	  useEffect(() => {
235	    if (!spriteName) return;
236	    api.cleanupLegacyChatServices(spriteName).catch(() => {});
237	  }, [spriteName]);
238	
239	  // Load chat session when chatId changes (or when forced via reloadNonce).
240	  useEffect(() => {
241	    if (chatId) {
242	      chat.loadSession();
243	    }
244	    // eslint-disable-next-line react-hooks/exhaustive-deps
245	  }, [chatId, reloadNonce]);
246	
247	  // Re-sync the current chat whenever the app returns from the background or lock screen.
248	  // The hook will reattach to a still-running exec session, or merge the on-disk transcript
249	  // if the agent finished while the app was suspended.
250	  useEffect(() => {
251	    const subscription = AppState.addEventListener('change', (nextState) => {
252	      const wasAway =
253	        appStateRef.current === 'inactive' || appStateRef.current === 'background';
254	      appStateRef.current = nextState;
255	      if (nextState === 'active' && wasAway && chatId) {
256	        setReloadNonce((n) => n + 1);
257	      }
258	    });
259	
260	    return () => subscription.remove();
261	  }, [chatId]);
262	
263	  // Auto-scroll on new messages
264	  useEffect(() => {
265	    if (chat.messages.length > 0) {
266	      setTimeout(() => {
267	        flatListRef.current?.scrollToEnd({ animated: true });
268	      }, 100);
269	    }
270	  }, [chat.messages.length, chat.messages[chat.messages.length - 1]?.content.length]);
271	
272	  // Update chat list with first message preview when messages change
273	  useEffect(() => {
274	    if (chatId && chat.messages.length > 0) {
275	      const firstUserMsg = chat.messages.find((m) => m.role === 'user');
276	      if (firstUserMsg) {
277	        const preview = firstUserMsg.content
278	          .filter((c): c is { type: 'text'; text: string } => c.type === 'text')
279	          .map((c) => c.text)
280	          .join(' ')
281	          .slice(0, 100);
282	
283	        const updated = chatListRef.current.map((c) =>
284	          c.id === chatId
285	            ? { ...c, lastUsed: Date.now(), firstMessagePreview: preview || c.firstMessagePreview }
286	            : c
287	        );
288	        commitChatList(updated);
289	        chatRepository.patch(chatId, {
290	          lastUsed: Date.now(),
291	          firstMessagePreview: preview || undefined,
292	        });
293	      }
294	    }
295	  }, [chat.messages.length, chatId, commitChatList]);
296	
297	  const handleSend = () => {
298	    chat.sendMessage();
299	  };
300	
301	  const handleTranscriptionProviderChange = useCallback(async (provider: TranscriptionProvider) => {
302	    setTranscriptionProvider(provider);
303	    await setSetting('transcriptionProvider', provider);
304	  }, []);
305	
306	  const createChat = useCallback(async (config: NewSessionConfig) => {
307	    // One useChat instance is shared across sessions. Detach the local stream
308	    // before switching so the remote exec can keep running and be reattached later.
309	    if (chat.isStreaming) chat.detachStream();
310	    const chats = chatListRef.current;
311	    const maxNumber = chats.reduce((max, c) => Math.max(max, c.chatNumber), 0);
312	    const newNumber = maxNumber + 1;
313	    const dir = normalizeWorkingDirectory(config.workingDirectory);
314	    const newChat: PersistedChat = {
315	      id: `${spriteName}-chat-${newNumber}`,
316	      spriteName,
317	      chatNumber: newNumber,
318	      provider: config.provider,
319	      workingDirectory: dir,
320	      createdAt: Date.now(),
321	      lastUsed: Date.now(),
322	      isClosed: false,
323	      lastSessionComplete: true,
324	      processedEventUUIDs: [],
325	    };
326	    commitChatList([...chats, newChat]);
327	    await chatRepository.upsert(newChat);
328	    setChatId(newChat.id);
329	    setChatName(`Session ${newNumber}`);
330	    setChatProvider(config.provider);
331	    setWorkingDirectory(dir);
332	    setClaudeSessionId(undefined);
333	    setCodexSessionId(undefined);
334	    setActiveRun(undefined);
335	    setChatListVisible(false);
336	    setSessionSheetMode(null);
337	    // Adding a conversation opens it.
338	    setTab('chats');
339	    setChatOpen(true);
340	  }, [chat.detachStream, chat.isStreaming, spriteName, commitChatList]);
341	
342	  // Change the directory of the *current* session (only allowed before its first message).
343	  const updateCurrentDirectory = useCallback(async (config: NewSessionConfig) => {
344	    const dir = normalizeWorkingDirectory(config.workingDirectory);
345	    setWorkingDirectory(dir);
346	    const updated = chatListRef.current.map((c) =>
347	      c.id === chatId ? { ...c, workingDirectory: dir } : c
348	    );
349	    commitChatList(updated);
350	    await chatRepository.patch(chatId, { workingDirectory: dir });
351	    setSessionSheetMode(null);
352	  }, [chatId, commitChatList]);
353	
354	  const handleSelectChat = useCallback((selectedChat: PersistedChat) => {
355	    const latestChat = chatListRef.current.find((c) => c.id === selectedChat.id) ?? selectedChat;
356	    if (latestChat.id === chatId) {
357	      setReloadNonce((n) => n + 1);
358	      setChatListVisible(false);
359	      setChatOpen(true);
360	      return;
361	    }
362	    // One useChat instance is shared across sessions, so detach any in-flight stream
363	    // before switching. The exec stays alive and is reattached when its chat reopens.
364	    if (chat.isStreaming) chat.detachStream();
365	    setChatId(latestChat.id);
366	    setChatName(latestChat.customName ?? `Session ${latestChat.chatNumber}`);
367	    setChatProvider(normalizeProvider(latestChat.provider));
368	    setClaudeSessionId(latestChat.claudeSessionId);
369	    setCodexSessionId(latestChat.codexSessionId);
370	    setActiveRun(latestChat.activeRun);
371	    setWorkingDirectory(latestChat.workingDirectory || defaultDirectory);
372	    setReloadNonce((n) => n + 1);
373	    // Update lastUsed
374	    const updated = chatListRef.current.map((c) =>
375	      c.id === latestChat.id ? { ...c, lastUsed: Date.now() } : c
376	    );
377	    commitChatList(updated);
378	    chatRepository.patch(latestChat.id, { lastUsed: Date.now() });
379	    setChatListVisible(false);
380	    setChatOpen(true);
381	  }, [chat.detachStream, chat.isStreaming, chatId, defaultDirectory, commitChatList]);
382	
383	  const handleDeleteChat = useCallback((target: PersistedChat) => {
384	    const remaining = chatListRef.current.filter((c) => c.id !== target.id);
385	    commitChatList(remaining);
386	    chatRepository.remove(target.id);
387	    if (target.id !== chatId) return;
388	    // The current chat was deleted; detach any live stream and fall back to the
389	    // most recent remaining conversation (or nothing, which shows the empty list).
390	    if (chat.isStreaming) chat.detachStream();
391	    if (remaining.length > 0) {
392	      const next = [...remaining].sort((a, b) => b.lastUsed - a.lastUsed)[0];
393	      setChatId(next.id);
394	      setChatName(next.customName ?? `Session ${next.chatNumber}`);
395	      setChatProvider(normalizeProvider(next.provider));
396	      setClaudeSessionId(next.claudeSessionId);
397	      setCodexSessionId(next.codexSessionId);
398	      setActiveRun(next.activeRun);
399	      setWorkingDirectory(next.workingDirectory || defaultDirectory);
400	      setReloadNonce((n) => n + 1);
401	    } else {
402	      setChatId('');
403	    }
404	    setChatOpen(false);
405	  }, [chat.detachStream, chat.isStreaming, chatId, defaultDirectory, commitChatList]);
406	
407	  // Resume a session discovered on the sprite (its on-disk transcript).
408	  // Reuses an existing local chat bound to the same session id, or creates one,
409	  // seeds it with the rendered transcript, and points the chat at provider-specific
410	  // resume id with the session's original cwd when available.
411	  const handleResumeSession = useCallback(
412	    async (session: AgentSessionSummary, messages: ChatMessage[]) => {
413	      if (chat.isStreaming) chat.detachStream();
414	      const dir = normalizeWorkingDirectory(session.cwd || defaultDirectory);
415	      const chats = chatListRef.current;
416	      const existing = chats.find((c) =>
417	        session.provider === 'codex'
418	          ? c.provider === 'codex' && c.codexSessionId === session.id
419	          : c.provider === 'claude' && c.claudeSessionId === session.id
420	      );
421	
422	      let target: PersistedChat;
423	      if (existing) {
424	        target = {
425	          ...existing,
426	          provider: session.provider,
427	          claudeSessionId: session.provider === 'claude' ? session.id : existing.claudeSessionId,
428	          codexSessionId: session.provider === 'codex' ? session.id : existing.codexSessionId,
429	          workingDirectory: dir,
430	          lastUsed: Date.now(),
431	        };
432	      } else {
433	        const maxNumber = chats.reduce((max, c) => Math.max(max, c.chatNumber), 0);
434	        target = {
435	          id: `${spriteName}-chat-${maxNumber + 1}`,
436	          spriteName,
437	          chatNumber: maxNumber + 1,
438	          provider: session.provider,
439	          claudeSessionId: session.provider === 'claude' ? session.id : undefined,
440	          codexSessionId: session.provider === 'codex' ? session.id : undefined,
441	          workingDirectory: dir,
442	          createdAt: Date.now(),
443	          lastUsed: Date.now(),
444	          isClosed: false,
445	          lastSessionComplete: true,
446	          processedEventUUIDs: [],
447	          firstMessagePreview: session.preview ? session.preview.slice(0, 100) : undefined,
448	        };
449	      }
450	
451	      const updated = existing
452	        ? chats.map((c) => (c.id === target.id ? target : c))
453	        : [...chats, target];
454	      commitChatList(updated);
455	      await chatRepository.upsert(target);
456	      await chatRepository.setMessages(target.id, messages);
457	
458	      setChatProvider(session.provider);
459	      setClaudeSessionId(session.provider === 'claude' ? session.id : target.claudeSessionId);
460	      setCodexSessionId(session.provider === 'codex' ? session.id : target.codexSessionId);
461	      setActiveRun(undefined);
462	      setWorkingDirectory(dir);
463	      setChatName(target.customName ?? `Session ${target.chatNumber}`);
464	      setChatId(target.id);
465	      setSessionBrowserVisible(false);
466	      setTab('chats');
467	      setChatOpen(true);
468	      // Force a reload even if chatId didn't change (resuming the open chat).
469	      setReloadNonce((n) => n + 1);
470	    },
471	    [chat.detachStream, chat.isStreaming, defaultDirectory, spriteName, commitChatList]
472	  );
473	
474	  const handleProviderChange = useCallback((nextProvider: AgentProvider) => {
475	    if (!chatId || chat.isStreaming || isProviderLocked) return;
476	    setChatProvider(nextProvider);
477	    const updated = chatListRef.current.map((c) =>
478	      c.id === chatId ? { ...c, provider: nextProvider } : c
479	    );
480	    commitChatList(updated);
481	    chatRepository.patch(chatId, { provider: nextProvider });
482	  }, [chat.isStreaming, chatId, isProviderLocked, commitChatList]);
483	
484	  useEffect(() => {
485	    if (!chat.codexAuthIssue) return;
486	    const isLocked = isProviderLocked;
487	    Alert.alert(
488	      'Codex Authentication Required',
489	      isLocked
490	        ? `${chat.codexAuthIssue}\n\nThis session is locked to Codex. Start a new Claude session now?`
491	        : `${chat.codexAuthIssue}\n\nSwitch this session to Claude now?`,
492	      [
493	        {
494	          text: 'Cancel',
495	          style: 'cancel',
496	          onPress: () => chat.clearCodexAuthIssue(),
497	        },
498	        {
499	          text: isLocked ? 'New Claude Session' : 'Switch to Claude',
500	          onPress: () => {
501	            if (isLocked) {
502	              createChat({ workingDirectory, provider: 'claude' });
503	            } else {
504	              handleProviderChange('claude');
505	            }
506	            chat.clearCodexAuthIssue();
507	          },
508	        },
509	      ]
510	    );
511	  }, [chat.codexAuthIssue, chat.clearCodexAuthIssue, createChat, handleProviderChange, isProviderLocked, workingDirectory]);
512	
513	  const handleInsertBashOutput = useCallback((text: string) => {
514	    chat.setInputText((prev: string) => (prev ? prev + '\n' + text : text));
515	  }, [chat.setInputText]);
516	
517	  // Active tool label for the chat view
518	  const activeToolLabel = chat.isStreaming
519	    ? getActiveToolLabel(chat.messages, workingDirectory)
520	    : undefined;
521	
522	  const tabItems: { key: Tab; label: string }[] = [
523	    { key: 'options', label: 'Options' },
524	    { key: 'chats', label: 'Chats' },
525	    { key: 'settings', label: 'Settings' },
526	  ];
527	
528	  return (
529	    <SafeAreaView style={[styles.container, { backgroundColor: colors.background }]} edges={['top']}>
530	      {/* Header */}
531	      <View style={[styles.header, { borderBottomColor: colors.border }]}>
532	        <Pressable onPress={() => (chatOpen ? setChatOpen(false) : router.back())} hitSlop={12}>
533	          <Text style={[styles.backButton, { color: colors.tint }]}>
534	            &#x2039; {chatOpen ? 'Chats' : 'Back'}
535	          </Text>
536	        </Pressable>
537	        <View style={styles.headerCenter}>
538	          {chatOpen ? (
539	            <>
540	              <Pressable onPress={() => setChatListVisible(true)} hitSlop={6}>
541	                <Text style={[styles.headerTitle, { color: colors.text }]} numberOfLines={1}>
542	                  {chatName} ▾
543	                </Text>
544	              </Pressable>
545	              <Text style={[styles.chatSubtitle, { color: colors.textSecondary }]} numberOfLines={1}>
546	                {providerDisplayName(chatProvider)} · {shortWorkingDirectory(workingDirectory)}
