887	// Settings Tab — checkpoints, accounts, sprite info, and delete. A lightweight
888	// sub-view switch keeps each nested scroller (CheckpointsList / SpriteAccountsTab)
889	// isolated and leaves room for more settings later.
890	function SettingsTab({
891	  sprite,
892	  isLoading,
893	  spriteName,
894	  workingDirectory,
895	  isActive,
896	  onSpriteUpdated,
897	}: {
898	  sprite: Sprite | null;
899	  isLoading: boolean;
900	  spriteName: string;
901	  workingDirectory: string;
902	  isActive: boolean;
903	  onSpriteUpdated: (sprite: Sprite) => void;
904	}) {
905	  const colors = useTheme();
906	  const [view, setView] = useState<SettingsView>('menu');
907	  const [isDeleting, setIsDeleting] = useState(false);
908	
909	  // Poll sprite status every 5 seconds while the Settings menu is showing.
910	  useEffect(() => {
911	    if (!isActive || view !== 'menu') return;
912	    const interval = setInterval(async () => {
913	      try {
914	        const s = await api.getSprite(spriteName);
915	        onSpriteUpdated(s);
916	      } catch {}
917	    }, 5000);
918	    return () => clearInterval(interval);
919	  }, [isActive, view, spriteName, onSpriteUpdated]);
920	
921	  const handleDelete = () => {
922	    Alert.alert(
923	      'Delete Sprite',
924	      `Are you sure you want to delete "${spriteName}"? This action cannot be undone.`,
925	      [
926	        { text: 'Cancel', style: 'cancel' },
927	        {
928	          text: 'Delete',
929	          style: 'destructive',
930	          onPress: async () => {
931	            setIsDeleting(true);
932	            try {
933	              await api.deleteSprite(spriteName);
934	              router.back();
935	            } catch (err: any) {
936	              Alert.alert('Error', err.message ?? 'Failed to delete sprite');
937	              setIsDeleting(false);
938	            }
939	          },
940	        },
941	      ]
942	    );
943	  };
944	
945	  if (view === 'checkpoints') {
946	    return (
947	      <SettingsSubView title="Checkpoints" onBack={() => setView('menu')}>
948	        <CheckpointsList spriteName={spriteName} />
949	      </SettingsSubView>
950	    );
951	  }
952	
953	  if (view === 'accounts') {
954	    return (
955	      <SettingsSubView title="Accounts" onBack={() => setView('menu')}>
956	        <SpriteAccountsTab spriteName={spriteName} isActive={isActive} />
957	      </SettingsSubView>
958	    );
959	  }
960	
961	  if (isLoading) {
962	    return (
963	      <View style={styles.centerView}>
964	        <ActivityIndicator size="large" color={colors.tint} />
965	      </View>
966	    );
967	  }
968	
969	  const infoRows: { label: string; value: string }[] = [];
970	  if (sprite) {
971	    infoRows.push(
972	      { label: 'Name', value: sprite.name },
973	      { label: 'Status', value: statusDisplayName(sprite.status) },
974	      { label: 'ID', value: sprite.id }
975	    );
976	    if (sprite.url) infoRows.push({ label: 'URL', value: sprite.url });
977	    if (sprite.created_at) {
978	      infoRows.push({ label: 'Created', value: new Date(sprite.created_at).toLocaleString() });
979	    }
980	    if (sprite.url_settings) infoRows.push({ label: 'Auth', value: sprite.url_settings.auth });
981	  }
982	  infoRows.push({ label: 'Work Dir', value: workingDirectory });
983	
984	  return (
985	    <ScrollView style={styles.tabScroll} contentContainerStyle={styles.tabScrollContent}>
986	      <Text style={[styles.sectionHeader, { color: colors.textSecondary }]}>CONFIGURATION</Text>
987	      <ConnectRow
988	        title="Checkpoints"
989	        subtitle="Create and restore filesystem checkpoints for this sprite."
990	        onPress={() => setView('checkpoints')}
991	      />
992	      <ConnectRow
993	        title="Accounts"
994	        subtitle="Connect Claude, Codex, and GitHub accounts for this sprite."
995	        onPress={() => setView('accounts')}
996	      />
997	
998	      {!sprite ? (
999	        <Text style={[styles.errorBarText, { color: colors.destructive, marginTop: Spacing.lg }]}>
1000	          Failed to load sprite info
1001	        </Text>
1002	      ) : (
1003	        <>
1004	          <Text style={[styles.sectionHeader, { color: colors.textSecondary }]}>SPRITE INFO</Text>
1005	          {infoRows.map((row) => (
1006	            <View key={row.label} style={[styles.infoRow, { borderBottomColor: colors.border }]}>
1007	              <Text style={[styles.infoLabel, { color: colors.textSecondary }]}>{row.label}</Text>
1008	              <Text
1009	                style={[styles.infoValue, { color: colors.text }]}
1010	                numberOfLines={1}
1011	                selectable
1012	              >
1013	                {row.value}
1014	              </Text>
1015	            </View>
1016	          ))}
1017	        </>
1018	      )}
1019	
1020	      <View style={styles.deleteButtonContainer}>
1021	        <Pressable
1022	          style={[styles.deleteButton, { borderColor: colors.destructive }]}
1023	          onPress={handleDelete}
1024	          disabled={isDeleting}
1025	        >
1026	          {isDeleting ? (
1027	            <ActivityIndicator size="small" color={colors.destructive} />
1028	          ) : (
1029	            <Text style={[styles.deleteButtonText, { color: colors.destructive }]}>
1030	              Delete Sprite
1031	            </Text>
1032	          )}
1033	        </Pressable>
1034	      </View>
1035	    </ScrollView>
1036	  );
1037	}
