1	import { Sprite, SpritesListResponse } from '@/models/sprite';
2	import { Checkpoint, CheckpointStreamEvent } from '@/models/checkpoint';
3	import { ServiceRequest, ServiceLogEvent, ServiceInfo } from '@/models/service';
4	import { Platform } from 'react-native';
5	import { loadToken } from './auth';
6	
7	const BASE_URL = Platform.OS === 'web' ? '/api/v1' : 'https://api.sprites.dev/v1';
8	const WS_BASE_URL = Platform.OS === 'web' ? 'ws://localhost:8082/v1' : 'wss://api.sprites.dev/v1';
9	
10	type RNWebSocketCtor = new (
11	  url: string,
12	  protocols?: string | string[] | null,
13	  options?: { headers?: Record<string, string> } | null
14	) => WebSocket;
15	
16	class AppError extends Error {
17	  constructor(public code: string, message: string, public statusCode?: number) {
18	    super(message);
19	    this.name = 'AppError';
20	  }
21	}
22	
23	function parseServiceEventLine(line: string): ServiceLogEvent | null {
24	  const trimmed = line.trim();
25	  if (!trimmed) return null;
26	
27	  if (
28	    trimmed.startsWith('event:') ||
29	    trimmed.startsWith('id:') ||
30	    trimmed.startsWith('retry:') ||
31	    trimmed.startsWith(':')
32	  ) {
33	    return null;
34	  }
35	
36	  const payload = trimmed.startsWith('data:') ? trimmed.slice(5).trim() : trimmed;
37	  if (!payload || payload === '[DONE]') return null;
38	
39	  try {
40	    return JSON.parse(payload) as ServiceLogEvent;
41	  } catch {
42	    return null;
43	  }
44	}
45	
46	async function getToken(): Promise<string> {
47	  const token = await loadToken('spritesToken');
48	  if (!token) throw new AppError('noToken', 'No Sprites API token');
49	  return token;
50	}
51	
52	async function apiRequest<T>(
53	  method: string,
54	  path: string,
55	  body?: unknown,
56	  timeout?: number
57	): Promise<T> {
58	  const token = await getToken();
59	  const url = `${BASE_URL}${path}`;
60	
61	  const controller = new AbortController();
62	  const timeoutId = timeout
63	    ? setTimeout(() => controller.abort(), timeout * 1000)
64	    : null;
65	
66	  try {
67	    const headers: Record<string, string> = {
68	      Authorization: `Bearer ${token}`,
69	      'Content-Type': 'application/json',
70	    };
71	
72	    const response = await fetch(url, {
73	      method,
74	      headers,
75	      body: body ? JSON.stringify(body) : undefined,
76	      signal: controller.signal,
77	    });
78	
79	    if (timeoutId) clearTimeout(timeoutId);
80	
81	    if (response.status === 401) throw new AppError('unauthorized', 'Unauthorized');
82	    if (response.status === 404) throw new AppError('notFound', 'Not found');
83	    if (!response.ok) {
84	      const text = await response.text().catch(() => '');
85	      throw new AppError('serverError', text || `Server error ${response.status}`, response.status);
86	    }
87	
88	    const text = await response.text();
89	    if (!text) return {} as T;
90	    return JSON.parse(text) as T;
91	  } catch (err) {
92	    if (timeoutId) clearTimeout(timeoutId);
93	    if (err instanceof AppError) throw err;
94	    throw new AppError('networkError', (err as Error).message);
95	  }
96	}
97	
98	// MARK: - Sprites
99	
