136	export async function createCheckpoint(spriteName: string, comment?: string): Promise<void> {
137	  const token = await getToken();
138	  const url = `${BASE_URL}/sprites/${spriteName}/checkpoint`;
139	
140	  const response = await fetch(url, {
141	    method: 'POST',
142	    headers: {
143	      Authorization: `Bearer ${token}`,
144	      'Content-Type': 'application/json',
145	    },
146	    body: JSON.stringify({ comment: comment ?? null }),
147	  });
148	
149	  if (!response.ok) {
150	    const text = await response.text().catch(() => '');
151	    throw new AppError('serverError', text || `Error ${response.status}`, response.status);
152	  }
153	
154	  // Consume NDJSON stream
155	  const reader = response.body?.getReader();
156	  if (reader) {
157	    const decoder = new TextDecoder();
158	    while (true) {
159	      const { done, value } = await reader.read();
160	      if (done) break;
161	      const text = decoder.decode(value, { stream: true });
162	      for (const line of text.split('\n')) {
163	        if (!line.trim()) continue;
164	        try {
165	          const event: CheckpointStreamEvent = JSON.parse(line);
166	          if (event.type === 'error') {
167	            throw new AppError('serverError', event.error ?? event.data ?? 'Checkpoint error');
168	          }
169	        } catch (e) {
170	          if (e instanceof AppError) throw e;
171	        }
172	      }
173	    }
174	  }
175	}
