271	export async function streamService(
272	  spriteName: string,
273	  serviceName: string,
274	  config: ServiceRequest,
275	  onEvent: (event: ServiceLogEvent) => void,
276	  signal?: AbortSignal,
277	  duration: string = '3600s'
278	): Promise<void> {
279	  const token = await getToken();
280	  const url = `${BASE_URL}/sprites/${spriteName}/services/${serviceName}?duration=${duration}`;
281	
282	  const response = await fetch(url, {
283	    method: 'PUT',
284	    headers: {
285	      Authorization: `Bearer ${token}`,
286	      'Content-Type': 'application/json',
287	    },
288	    body: JSON.stringify(config),
289	    signal,
290	  });
291	
292	  if (response.status === 401) throw new AppError('unauthorized', 'Unauthorized');
293	  if (response.status === 404) throw new AppError('notFound', 'Not found');
294	  if (!response.ok) {
295	    throw new AppError('serverError', `Service error ${response.status}`, response.status);
296	  }
297	
298	  const reader = response.body?.getReader();
299	  const decoder = new TextDecoder();
300	  let buffer = '';
301	  const consumeChunk = (chunk: string) => {
302	    buffer += chunk;
303	    const lines = buffer.split('\n');
304	    buffer = lines.pop() ?? '';
305	
306	    for (const line of lines) {
307	      const event = parseServiceEventLine(line);
308	      if (event) onEvent(event);
309	    }
310	  };
311	
312	  if (reader) {
313	    while (true) {
314	      const { done, value } = await reader.read();
315	      if (done) break;
316	      consumeChunk(decoder.decode(value, { stream: true }));
317	    }
318	  } else {
319	    // Some RN runtimes don't expose a streaming reader; fall back to full text parse.
320	    const text = await response.text();
321	    if (text) consumeChunk(text.endsWith('\n') ? text : `${text}\n`);
322	  }
323	
324	  // Process remaining buffer
325	  if (buffer.trim()) {
326	    const event = parseServiceEventLine(buffer);
327	    if (event) onEvent(event);
328	  }
329	}
