387	
388	export interface ExecStdinWriter {
389	  write: (text: string) => void;
390	  writeBytes: (bytes: Uint8Array) => void;
391	}
392	
393	export interface StreamExecOptions {
394	  attachSessionId?: string;
395	  path?: string;
396	  maxRunAfterDisconnect?: string;
397	  tty?: boolean;
398	  stdin?: boolean;
399	  onStdinReady?: (writer: ExecStdinWriter) => void;
400	  onSessionId?: (sessionId: string) => void;
401	  onDisconnectBeforeExit?: () => void;
402	}
403	
404	function createAbortError(): Error {
405	  const error = new Error('Aborted');
406	  error.name = 'AbortError';
407	  return error;
408	}
409	
410	function makeExecWsUrl(
411	  spriteName: string,
412	  command: string[],
413	  token: string,
414	  options: StreamExecOptions
415	): string {
416	  if (options.attachSessionId) {
417	    const params = new URLSearchParams();
418	    if (Platform.OS === 'web') params.set('token', token);
419	    const query = params.toString();
420	    return `${WS_BASE_URL}/sprites/${encodeURIComponent(spriteName)}/exec/${encodeURIComponent(options.attachSessionId)}${query ? `?${query}` : ''}`;
421	  }
422	
423	  const params = new URLSearchParams();
424	  for (const part of command) params.append('cmd', part);
425	  params.set('path', options.path ?? command[0] ?? 'bash');
426	  params.set('tty', options.tty ? 'true' : 'false');
427	  params.set('stdin', options.stdin ? 'true' : 'false');
428	  params.set('max_run_after_disconnect', options.maxRunAfterDisconnect ?? '0s');
429	  if (Platform.OS === 'web') params.set('token', token);
430	
431	  return `${WS_BASE_URL}/sprites/${encodeURIComponent(spriteName)}/exec?${params.toString()}`;
432	}
433	
434	async function messageDataToBytes(data: unknown): Promise<Uint8Array | undefined> {
435	  if (data instanceof ArrayBuffer) return new Uint8Array(data);
436	  if (ArrayBuffer.isView(data)) {
437	    return new Uint8Array(data.buffer, data.byteOffset, data.byteLength);
438	  }
439	  if (typeof Blob !== 'undefined' && data instanceof Blob) {
440	    return new Uint8Array(await data.arrayBuffer());
441	  }
442	  return undefined;
443	}
444	
445	async function messageDataToText(data: unknown): Promise<string> {
446	  if (typeof data === 'string') return data;
447	  const bytes = await messageDataToBytes(data);
448	  if (bytes) return new TextDecoder().decode(bytes);
449	  return String(data ?? '');
450	}
451	
452	function extractExecSessionId(payload: unknown): string | undefined {
453	  if (!payload || typeof payload !== 'object') return undefined;
454	  const obj = payload as Record<string, unknown>;
455	  const direct = obj.session_id ?? obj.sessionId;
456	  if (typeof direct === 'string') return direct;
457	  if (typeof direct === 'number') return String(direct);
458	  return undefined;
459	}
460	
461	function parseExecExitCode(bytes: Uint8Array): number {
462	  if (bytes.length === 0) return 0;
463	  if (bytes.length === 1) return bytes[0];
464	
465	  const text = new TextDecoder().decode(bytes).trim();
466	  const parsed = Number(text);
467	  return Number.isFinite(parsed) ? parsed : bytes[0];
468	}
469	
470	function stringLooksLikeBinaryFrame(text: string): boolean {
471	  if (!text) return false;
472	  const streamId = text.charCodeAt(0);
473	  return streamId >= 0 && streamId <= 4;
474	}
475	
476	function stringToBytes(text: string): Uint8Array {
477	  return Uint8Array.from(Array.from(text, (ch) => ch.charCodeAt(0) & 0xff));
478	}
479	
480	function textToUtf8Bytes(text: string): Uint8Array {
481	  if (typeof TextEncoder !== 'undefined') return new TextEncoder().encode(text);
482	
483	  const encoded = unescape(encodeURIComponent(text));
484	  return Uint8Array.from(Array.from(encoded, (ch) => ch.charCodeAt(0) & 0xff));
485	}
486	
487	function makeExecStdinFrame(payload: Uint8Array): ArrayBuffer {
488	  const frame = new Uint8Array(payload.length + 1);
489	  frame[0] = 0;
490	  frame.set(payload, 1);
491	  return frame.buffer;
492	}
