494	/**
495	 * Stream a one-shot command through the Exec API.
496	 *
497	 * Chat turns must not use the Services API: services are persistent supervised
498	 * processes and may be restarted by the sprite service manager, replaying the
499	 * same prompt into `claude --resume`. Exec sessions do not auto-restart, and
500	 * `max_run_after_disconnect` explicitly controls disconnect behavior.
501	 */
502	export async function streamExec(
503	  spriteName: string,
504	  command: string[],
505	  onEvent: (event: ServiceLogEvent) => void,
506	  signal?: AbortSignal,
507	  options: StreamExecOptions = {}
508	): Promise<void> {
509	  const token = await getToken();
510	  const url = makeExecWsUrl(spriteName, command, token, options);
511	  const stdoutDecoder = new TextDecoder();
512	  const stderrDecoder = new TextDecoder();
513	
514	  return new Promise((resolve, reject) => {
515	    if (signal?.aborted) {
516	      reject(createAbortError());
517	      return;
518	    }
519	
520	    let socket: WebSocket | null = null;
521	    let settled = false;
522	    let sawExit = false;
523	
524	    const cleanup = () => {
525	      signal?.removeEventListener('abort', handleAbort);
526	      if (socket) {
527	        socket.onopen = null;
528	        socket.onmessage = null;
529	        socket.onerror = null;
530	        socket.onclose = null;
531	      }
532	    };
533	
534	    const settle = (err?: Error) => {
535	      if (settled) return;
536	      settled = true;
537	      cleanup();
538	      if (err) {
539	        reject(err);
540	      } else {
541	        onEvent({ type: 'complete' });
542	        resolve();
543	      }
544	    };
545	
546	    const closeSocket = () => {
547	      if (!socket) return;
548	      if (socket.readyState === WebSocket.CLOSED || socket.readyState === WebSocket.CLOSING) return;
549	      socket.close();
550	    };
551	
552	    const writeStdinBytes = (bytes: Uint8Array) => {
553	      if (!socket || socket.readyState !== WebSocket.OPEN) {
554	        throw new AppError('networkError', 'Exec WebSocket is not open');
555	      }
556	      socket.send(makeExecStdinFrame(bytes));
557	    };
558	
559	    const stdinWriter: ExecStdinWriter = {
560	      write: (text: string) => writeStdinBytes(textToUtf8Bytes(text)),
561	      writeBytes: writeStdinBytes,
562	    };
563	
564	    function handleAbort() {
565	      closeSocket();
566	      settle(createAbortError());
567	    }
568	
569	    const handleJsonMessage = (payload: unknown): boolean => {
570	      if (!payload || typeof payload !== 'object') return false;
571	      const obj = payload as Record<string, unknown>;
572	      const sessionId = extractExecSessionId(obj);
573	      if (sessionId) options.onSessionId?.(sessionId);
574	
575	      if (obj.type === 'session_info') {
576	        onEvent({ type: 'started' });
577	        return true;
578	      }
579	
580	      if (obj.type === 'exit') {
581	        sawExit = true;
582	        const exitCode =
583	          typeof obj.exit_code === 'number' ? obj.exit_code :
584	          typeof obj.exitCode === 'number' ? obj.exitCode :
585	          0;
586	        onEvent({ type: 'exit', exit_code: exitCode });
587	        closeSocket();
588	        return true;
589	      }
590	
591	      return false;
592	    };
593	
594	    const handleTextMessage = (text: string): boolean => {
595	      try {
596	        return handleJsonMessage(JSON.parse(text));
597	      } catch {
598	        return false;
599	      }
600	    };
601	
602	    const handleBinaryMessage = (bytes: Uint8Array) => {
603	      if (bytes.length === 0) return;
604	      const streamId = bytes[0];
605	      const payload = bytes.slice(1);
606	
607	      if (streamId === 1) {
608	        const data = stdoutDecoder.decode(payload, { stream: true });
609	        if (data) onEvent({ type: 'stdout', data });
610	      } else if (streamId === 2) {
611	        const data = stderrDecoder.decode(payload, { stream: true });
612	        if (data) onEvent({ type: 'stderr', data });
613	      } else if (streamId === 3) {
614	        const stdoutRemainder = stdoutDecoder.decode();
615	        const stderrRemainder = stderrDecoder.decode();
616	        if (stdoutRemainder) onEvent({ type: 'stdout', data: stdoutRemainder });
617	        if (stderrRemainder) onEvent({ type: 'stderr', data: stderrRemainder });
618	        sawExit = true;
619	        onEvent({ type: 'exit', exit_code: parseExecExitCode(payload) });
620	        closeSocket();
621	      }
622	    };
623	
624	    signal?.addEventListener('abort', handleAbort, { once: true });
625	
626	    if (Platform.OS === 'web') {
627	      socket = new WebSocket(url);
628	    } else {
629	      const RNWebSocket = WebSocket as unknown as RNWebSocketCtor;
630	      socket = new RNWebSocket(url, undefined, {
631	        headers: {
632	          Authorization: `Bearer ${token}`,
633	        },
634	      });
635	    }
636	
637	    socket.binaryType = 'arraybuffer';
638	
639	    socket.onopen = () => {
640	      onEvent({ type: 'started' });
641	      try {
642	        options.onStdinReady?.(stdinWriter);
643	      } catch (err) {
644	        settle(err as Error);
645	      }
646	    };
647	
648	    socket.onmessage = async (event) => {
649	      try {
650	        if (typeof event.data === 'string') {
651	          if (stringLooksLikeBinaryFrame(event.data)) {
652	            handleBinaryMessage(stringToBytes(event.data));
653	            return;
654	          }
655	          if (!handleTextMessage(event.data)) {
656	            onEvent({ type: 'stdout', data: event.data });
657	          }
658	          return;
659	        }
660	
661	        const bytes = await messageDataToBytes(event.data);
662	        if (bytes) {
663	          handleBinaryMessage(bytes);
664	          return;
665	        }
666	
667	        const text = await messageDataToText(event.data);
668	        if (!handleTextMessage(text)) {
669	          onEvent({ type: 'stdout', data: text });
670	        }
671	      } catch (err) {
672	        settle(err as Error);
673	      }
674	    };
675	
676	    socket.onerror = () => {
677	      closeSocket();
678	      settle(new AppError('networkError', 'Exec WebSocket error'));
679	    };
680	
681	    socket.onclose = () => {
682	      if (signal?.aborted) {
683	        settle(createAbortError());
684	        return;
685	      }
686	      if (!sawExit) {
687	        if (options.onDisconnectBeforeExit) {
688	          options.onDisconnectBeforeExit();
689	        } else {
690	          onEvent({ type: 'exit', exit_code: 0 });
691	        }
692	      }
693	      settle();
694	    };
695	  });
696	}
