698	/**
699	 * Start a long-running service and let it keep running in the background.
700	 * `streamService` only resolves when the service exits, so this fires it without
701	 * awaiting and resolves `started` once the first lifecycle event arrives (or after
702	 * `settleMs`). Aborting the returned controller stops *streaming logs*; use
703	 * `deleteService` to actually stop the service.
704	 */
705	export function startBackgroundService(
706	  spriteName: string,
707	  serviceName: string,
708	  config: ServiceRequest,
709	  onEvent?: (event: ServiceLogEvent) => void,
710	  settleMs: number = 1500
711	): { controller: AbortController; started: Promise<void> } {
712	  const controller = new AbortController();
713	  const started = new Promise<void>((resolve) => {
714	    let settled = false;
715	    const settle = () => {
716	      if (settled) return;
717	      settled = true;
718	      resolve();
719	    };
720	    const timer = setTimeout(settle, settleMs);
721	    streamService(
722	      spriteName,
723	      serviceName,
724	      config,
725	      (event) => {
726	        onEvent?.(event);
727	        if (event.type === 'started' || event.type === 'stdout' || event.type === 'stderr') {
728	          settle();
729	        }
730	      },
731	      controller.signal
732	    )
733	      .catch((err) => {
734	        if ((err as Error)?.name !== 'AbortError') {
735	          onEvent?.({ type: 'error', data: (err as Error).message });
736	        }
737	      })
738	      .finally(() => {
739	        clearTimeout(timer);
740	        settle();
741	      });
742	  });
743	  return { controller, started };
744	}
