    'set -uo pipefail',
    `cd ${quotedWorkingDirectory} 2>/dev/null || cd /tmp`,
    `AUDIO=${quotedAudio}`,
    'OUT_DIR="$(mktemp -d /tmp/wisp-dictation.XXXXXX)"',
